/**
 * html5-qrcode vendored implementation
 * Supports modern getUserMedia camera scanning & image file scanning.
 * Uses native BarcodeDetector API with graceful fallback.
 */
(function(window) {
  'use strict';

  class Html5Qrcode {
    constructor(elementId, verbose = false) {
      this.elementId = elementId;
      this.verbose = verbose;
      this.container = document.getElementById(elementId);
      this.stream = null;
      this.video = null;
      this.canvas = null;
      this.context = null;
      this.scanningInterval = null;
      this.isScanning = false;
      this.detector = null;

      if ('BarcodeDetector' in window) {
        try {
          this.detector = new window.BarcodeDetector({ formats: ['qr_code'] });
        } catch (e) {
          this.detector = null;
        }
      }
    }

    static async getCameras() {
      if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) {
        throw new Error("MediaDevices API not supported on this browser or origin is not HTTPS/localhost.");
      }
      const devices = await navigator.mediaDevices.enumerateDevices();
      const videoDevices = devices.filter(d => d.kind === 'videoinput');
      return videoDevices.map(d => ({
        id: d.deviceId,
        label: d.label || `Camera ${d.deviceId.substring(0, 5)}`
      }));
    }

    async start(cameraIdOrConfig, config, qrCodeSuccessCallback, qrCodeErrorCallback) {
      if (this.isScanning) {
        throw new Error("Scanning is already in progress.");
      }

      if (!this.container) {
        throw new Error(`Element with id '${this.elementId}' not found.`);
      }

      // Build media constraints
      let constraints = { video: true, audio: false };
      if (typeof cameraIdOrConfig === 'string') {
        constraints.video = { deviceId: { exact: cameraIdOrConfig } };
      } else if (typeof cameraIdOrConfig === 'object') {
        if (cameraIdOrConfig.facingMode) {
          constraints.video = { facingMode: cameraIdOrConfig.facingMode };
        } else if (cameraIdOrConfig.deviceId) {
          constraints.video = { deviceId: cameraIdOrConfig.deviceId };
        }
      }

      try {
        this.stream = await navigator.mediaDevices.getUserMedia(constraints);
      } catch (err) {
        // Fallback to basic video if exact constraint fails
        if (constraints.video && typeof constraints.video === 'object') {
          this.stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
        } else {
          throw err;
        }
      }

      // Setup DOM
      this.container.innerHTML = '';
      this.video = document.createElement('video');
      this.video.setAttribute('autoplay', 'true');
      this.video.setAttribute('muted', 'true');
      this.video.setAttribute('playsinline', 'true');
      this.video.style.width = '100%';
      this.video.style.height = '100%';
      this.video.style.objectFit = 'cover';
      this.video.srcObject = this.stream;

      this.canvas = document.createElement('canvas');
      this.context = this.canvas.getContext('2d', { willReadFrequently: true });

      this.container.appendChild(this.video);
      await this.video.play();

      this.isScanning = true;
      const fps = (config && config.fps) ? config.fps : 10;
      const intervalMs = Math.round(1000 / fps);

      this.scanningInterval = setInterval(async () => {
        if (!this.isScanning || !this.video || this.video.readyState < 2) return;

        try {
          if (this.detector) {
            const barcodes = await this.detector.detect(this.video);
            if (barcodes && barcodes.length > 0) {
              const result = barcodes[0].rawValue;
              if (result) {
                qrCodeSuccessCallback(result, barcodes[0]);
                return;
              }
            }
          } else {
            // Software scan fallback using Canvas image data analysis
            const w = this.video.videoWidth;
            const h = this.video.videoHeight;
            if (w && h) {
              this.canvas.width = w;
              this.canvas.height = h;
              this.context.drawImage(this.video, 0, 0, w, h);
              // Check if jsQR is available on window
              if (window.jsQR) {
                const imgData = this.context.getImageData(0, 0, w, h);
                const code = window.jsQR(imgData.data, w, h);
                if (code && code.data) {
                  qrCodeSuccessCallback(code.data, code);
                  return;
                }
              }
            }
          }
        } catch (scanErr) {
          if (qrCodeErrorCallback) {
            qrCodeErrorCallback(scanErr);
          }
        }
      }, intervalMs);
    }

    async stop() {
      this.isScanning = false;
      if (this.scanningInterval) {
        clearInterval(this.scanningInterval);
        this.scanningInterval = null;
      }
      if (this.stream) {
        this.stream.getTracks().forEach(track => track.stop());
        this.stream = null;
      }
      if (this.video) {
        this.video.srcObject = null;
        this.video.remove();
        this.video = null;
      }
      if (this.container) {
        this.container.innerHTML = '';
      }
      return Promise.resolve();
    }

    async scanFile(imageFile, showImage = false) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = async (e) => {
          const img = new Image();
          img.onload = async () => {
            try {
              if (this.detector) {
                const barcodes = await this.detector.detect(img);
                if (barcodes && barcodes.length > 0 && barcodes[0].rawValue) {
                  return resolve(barcodes[0].rawValue);
                }
              }

              // Canvas fallback
              const c = document.createElement('canvas');
              c.width = img.naturalWidth || img.width;
              c.height = img.naturalHeight || img.height;
              const ctx = c.getContext('2d', { willReadFrequently: true });
              ctx.drawImage(img, 0, 0);

              if (window.jsQR) {
                const imgData = ctx.getImageData(0, 0, c.width, c.height);
                const code = window.jsQR(imgData.data, c.width, c.height);
                if (code && code.data) {
                  return resolve(code.data);
                }
              }

              reject(new Error("No QR code detected in the selected image."));
            } catch (err) {
              reject(err);
            }
          };
          img.onerror = () => reject(new Error("Failed to load image file."));
          img.src = e.target.result;
        };
        reader.onerror = () => reject(new Error("Failed to read image file."));
        reader.readAsDataURL(imageFile);
      });
    }
  }

  window.Html5Qrcode = Html5Qrcode;
  window.Html5QrcodeSupportedFormats = { QR_CODE: 0 };
})(window);

